arguments.command:
cd /tmp && mkdir -p binlog-reader && cd binlog-reader && cat > Program.cs << 'EOF'
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Print all errors and warnings
build.VisitAllChildren<Error>(e => {
    Console.WriteLine($"ERROR [{e.ProjectFile}]");
    Console.WriteLine($"  Code: {e.Code}");
    Console.WriteLine($"  File: {e.File}({e.LineNumber},{e.ColumnNumber})");
    Console.WriteLine($"  Message: {e.Message}");
    Console.WriteLine();
});

build.VisitAllChildren<Warning>(w => {
    Console.WriteLine($"WARNING [{w.ProjectFile}]");
    Console.WriteLine($"  Code: {w.Code}");
    Console.WriteLine($"  File: {w.File}({w.LineNumber},{w.ColumnNumber})");
    Console.WriteLine($"  Message: {w.Message}");
    Console.WriteLine();
});

// Show project build results
Console.WriteLine("=== PROJECT BUILD RESULTS ===");
build.VisitAllChildren<Project>(p => {
    Console.WriteLine($"Project: {p.Name} -> Succeeded: {p.Succeeded}");
});
EOF

